CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(320) NOT NULL UNIQUE, password_hash text NOT NULL, full_name varchar(200) NOT NULL, phone varchar(40), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_role (user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, role varchar(32) NOT NULL CHECK (role IN ('GUEST','RECEPTIONIST','HOTEL_MANAGER','SYSTEM_ADMIN')), PRIMARY KEY(user_id, role));
CREATE TABLE auth_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_session_valid_idx ON auth_session(token_hash,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE hotel (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(200) NOT NULL, slug varchar(220) NOT NULL UNIQUE, description text, address text NOT NULL, city varchar(120) NOT NULL, country varchar(120) NOT NULL, timezone varchar(80) NOT NULL DEFAULT 'UTC', status varchar(24) NOT NULL DEFAULT 'PENDING_APPROVAL' CHECK(status IN ('PENDING_APPROVAL','APPROVED','SUSPENDED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX hotel_city_status_idx ON hotel(city,status);
CREATE TABLE hotel_staff (hotel_id uuid NOT NULL REFERENCES hotel(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, staff_role varchar(32) NOT NULL CHECK(staff_role IN ('RECEPTIONIST','HOTEL_MANAGER')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(hotel_id,user_id));
CREATE TABLE amenity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(100) NOT NULL UNIQUE);
CREATE TABLE hotel_amenity (hotel_id uuid REFERENCES hotel(id) ON DELETE CASCADE, amenity_id uuid REFERENCES amenity(id) ON DELETE CASCADE, PRIMARY KEY(hotel_id,amenity_id));
CREATE TABLE hotel_image (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hotel_id uuid NOT NULL REFERENCES hotel(id) ON DELETE CASCADE, object_key text NOT NULL, alt_text varchar(250), sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE room_type (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hotel_id uuid NOT NULL REFERENCES hotel(id) ON DELETE CASCADE, name varchar(160) NOT NULL, description text, capacity integer NOT NULL CHECK(capacity > 0), base_price numeric(19,4) NOT NULL CHECK(base_price >= 0), currency char(3) NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(hotel_id,name));
CREATE TABLE room (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hotel_id uuid NOT NULL REFERENCES hotel(id), room_type_id uuid NOT NULL REFERENCES room_type(id), room_number varchar(40) NOT NULL, operational_status varchar(24) NOT NULL DEFAULT 'AVAILABLE' CHECK(operational_status IN ('AVAILABLE','OUT_OF_SERVICE','CLEANING')), UNIQUE(hotel_id,room_number));
CREATE INDEX room_type_inventory_idx ON room(room_type_id,operational_status);
CREATE TABLE pricing_rule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_type_id uuid NOT NULL REFERENCES room_type(id) ON DELETE CASCADE, starts_on date NOT NULL, ends_on date NOT NULL, nightly_price numeric(19,4) NOT NULL CHECK(nightly_price >= 0), currency char(3) NOT NULL, priority integer NOT NULL DEFAULT 0, CHECK(ends_on > starts_on));
CREATE TABLE cancellation_policy (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hotel_id uuid NOT NULL REFERENCES hotel(id) ON DELETE CASCADE, name varchar(160) NOT NULL, free_cancel_hours integer NOT NULL DEFAULT 0 CHECK(free_cancel_hours >= 0), refund_percent numeric(5,2) NOT NULL CHECK(refund_percent BETWEEN 0 AND 100), active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX cancellation_policy_one_active_per_hotel ON cancellation_policy(hotel_id) WHERE active;
CREATE TABLE reservation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guest_id uuid NOT NULL REFERENCES app_user(id), hotel_id uuid NOT NULL REFERENCES hotel(id), policy_id uuid REFERENCES cancellation_policy(id), check_in date NOT NULL, check_out date NOT NULL, status varchar(24) NOT NULL CHECK(status IN ('CREATED','PENDING_PAYMENT','CONFIRMED','CHECKED_IN','CHECKED_OUT','COMPLETED','EXPIRED','CANCELLED')), currency char(3) NOT NULL, total_amount numeric(19,4) NOT NULL CHECK(total_amount >= 0), idempotency_key varchar(160) NOT NULL, hold_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(check_out > check_in), UNIQUE(guest_id,idempotency_key));
CREATE INDEX reservation_guest_history_idx ON reservation(guest_id,created_at DESC);
CREATE INDEX reservation_hotel_dates_idx ON reservation(hotel_id,check_in,check_out,status);
CREATE TABLE reservation_room (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL REFERENCES reservation(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES room(id), room_type_name varchar(160) NOT NULL, nightly_rates jsonb NOT NULL, line_total numeric(19,4) NOT NULL CHECK(line_total >= 0), currency char(3) NOT NULL);
-- A separate occupancy row carries the date range so PostgreSQL can enforce the
-- exclusion constraint directly. Hold expiry/cancellation marks it inactive.
CREATE TABLE room_occupancy (reservation_room_id uuid PRIMARY KEY REFERENCES reservation_room(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES room(id), stay daterange NOT NULL, active boolean NOT NULL DEFAULT true, CHECK(NOT isempty(stay)));
ALTER TABLE room_occupancy ADD CONSTRAINT room_occupancy_no_overlap EXCLUDE USING gist (room_id WITH =, stay WITH &&) WHERE (active);
CREATE INDEX room_occupancy_active_idx ON room_occupancy(room_id) WHERE active;
CREATE TABLE payment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL REFERENCES reservation(id), provider varchar(60) NOT NULL, provider_reference varchar(240), idempotency_key varchar(160) NOT NULL UNIQUE, amount numeric(19,4) NOT NULL CHECK(amount >= 0), currency char(3) NOT NULL, status varchar(32) NOT NULL CHECK(status IN ('CREATED','PENDING','AUTHORIZED','DECLINED','FAILED','REFUNDED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_webhook_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider varchar(60) NOT NULL, event_id varchar(240) NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, outcome varchar(40), UNIQUE(provider,event_id));
CREATE TABLE cancellation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL UNIQUE REFERENCES reservation(id), policy_snapshot jsonb NOT NULL, refund_amount numeric(19,4) NOT NULL CHECK(refund_amount >= 0), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cancellation_id uuid NOT NULL REFERENCES cancellation(id), payment_id uuid NOT NULL REFERENCES payment(id), provider_reference varchar(240), amount numeric(19,4) NOT NULL CHECK(amount >= 0), status varchar(24) NOT NULL CHECK(status IN ('PENDING','SUCCEEDED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE check_in_record (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL REFERENCES reservation(id), action varchar(12) NOT NULL CHECK(action IN ('CHECK_IN','CHECK_OUT')), staff_user_id uuid NOT NULL REFERENCES app_user(id), occurred_at timestamptz NOT NULL DEFAULT now(), notes text);
CREATE TABLE reservation_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL REFERENCES reservation(id) ON DELETE CASCADE, from_status varchar(24), to_status varchar(24) NOT NULL, actor_user_id uuid REFERENCES app_user(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user(id), reservation_id uuid REFERENCES reservation(id), channel varchar(20) NOT NULL, template varchar(100) NOT NULL, status varchar(24) NOT NULL DEFAULT 'PENDING', provider_reference varchar(240), created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES app_user(id), hotel_id uuid REFERENCES hotel(id), action varchar(120) NOT NULL, entity_type varchar(80) NOT NULL, entity_id uuid, details jsonb, created_at timestamptz NOT NULL DEFAULT now());
